// Generates src/dialog/java_letter_or_digit.rs: the UTF-16 code units for which Java's Character.isLetterOrDigit(char)
// is true, as inclusive ranges (StringTemplate.isValidVariableName iterates chars, so surrogates are never valid).
//   java GenLetterOrDigit.java > crates/mc-protocol/src/dialog/java_letter_or_digit.rs
public class GenLetterOrDigit {
    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder();
        sb.append("//! Generated by tests/fixtures/dialog/GenLetterOrDigit.java (JDK ").append(System.getProperty("java.version")).append("): do not edit.\n\n");
        sb.append("/// Inclusive UTF-16 code unit ranges where `Character.isLetterOrDigit(char)` holds.\n");
        sb.append("pub(super) static LETTER_OR_DIGIT: &[(u16, u16)] = &[\n");
        int start = -1;
        int n = 0;
        for (int c = 0; c <= 0x10000; c++) {
            boolean on = c < 0x10000 && Character.isLetterOrDigit((char) c);
            if (on && start < 0) start = c;
            if (!on && start >= 0) {
                sb.append(String.format("    (0x%04X, 0x%04X),\n", start, c - 1));
                start = -1;
                n++;
            }
        }
        sb.append("];\n");
        System.out.print(sb);
    }
}
